.wallet-matrix-4x3 {
  --wm-bg: #0f1419;
  --wm-surface: #1a1f2e;
  --wm-surface-elevated: #222838;
  --wm-border: #2a3142;
  --wm-text-primary: #e8eaed;
  --wm-text-secondary: #9aa0a6;
  --wm-text-tertiary: #5f6368;
  --wm-accent: #34a853;
  --wm-crypto: #8ab4f8;
  --wm-radius: 6px;
  --wm-gap: 12px;

  width: 100%;
  height: 100%;
  background: var(--wm-bg);
  border-radius: 8px;
  padding: 20px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--wm-gap);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  overflow: hidden;
}

.wm-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-shrink: 0;
}

.wm-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--wm-text-primary);
  letter-spacing: -0.01em;
}

.wm-total {
  font-size: 12px;
  color: var(--wm-text-secondary);
  font-weight: 500;
}

.wm-primary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--wm-gap);
  flex-shrink: 0;
}

.wm-card {
  background: var(--wm-surface);
  border: 1px solid var(--wm-border);
  border-radius: var(--wm-radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: background 0.15s ease;
}

.wm-card:hover {
  background: var(--wm-surface-elevated);
}

.wm-card-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.wm-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  background: var(--wm-surface-elevated);
  border: 1px solid var(--wm-border);
}

.wm-badge {
  font-size: 10px;
  font-weight: 600;
  color: var(--wm-accent);
  background: rgba(52, 168, 83, 0.12);
  padding: 2px 8px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.wm-badge-crypto {
  color: var(--wm-crypto);
  background: rgba(138, 180, 248, 0.12);
}

.wm-balance {
  font-size: 22px;
  font-weight: 700;
  color: var(--wm-text-primary);
  letter-spacing: -0.02em;
  line-height: 1.2;
  word-break: break-all;
}

.wm-currency {
  font-size: 12px;
  font-weight: 600;
  color: var(--wm-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.wm-divider {
  height: 1px;
  background: var(--wm-border);
  flex-shrink: 0;
}

.wm-secondary-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

.wm-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 12px;
  border-radius: var(--wm-radius);
  transition: background 0.12s ease;
}

.wm-row:hover {
  background: var(--wm-surface);
}

.wm-row-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.wm-row-icon {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  background: var(--wm-surface-elevated);
  border: 1px solid var(--wm-border);
  flex-shrink: 0;
}

.wm-row-code {
  font-size: 13px;
  font-weight: 600;
  color: var(--wm-text-primary);
  min-width: 36px;
}

.wm-row-name {
  font-size: 12px;
  color: var(--wm-text-tertiary);
}

.wm-row-balance {
  font-size: 13px;
  font-weight: 600;
  color: var(--wm-text-primary);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 768px) {
  .wallet-matrix-4x3 {
    padding: 16px;
  }

  .wm-primary-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .wm-balance {
    font-size: 18px;
  }

  .wm-secondary-list {
    gap: 4px;
  }
}

@media (max-width: 480px) {
  .wm-primary-grid {
    grid-template-columns: 1fr;
  }

  .wm-row-name {
    display: none;
  }
}

