.qa-tileboard {
  --qa-bg: #ffffff;
  --qa-surface: #f8fafc;
  --qa-border: #e2e8f0;
  --qa-border-hover: #cbd5e1;
  --qa-text-primary: #0f172a;
  --qa-text-secondary: #64748b;
  --qa-text-muted: #94a3b8;
  --qa-accent: #2563eb;
  --qa-accent-light: #dbeafe;
  --qa-accent-soft: #eff6ff;
  --qa-success: #059669;
  --qa-success-light: #d1fae5;
  --qa-warning: #d97706;
  --qa-warning-light: #fef3c7;
  --qa-live: #dc2626;
  --qa-live-light: #fee2e2;
  --qa-radius: 6px;
  --qa-gap: 8px;

  width: 100%;
  height: 100%;
  min-height: 0;
  background: var(--qa-bg);
  border-radius: var(--qa-radius);
  border: 1px solid var(--qa-border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.qa-indicator-band {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: var(--qa-surface);
  border-bottom: 1px solid var(--qa-border);
  flex-shrink: 0;
}

.qa-indicator-left {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.qa-indicator-label {
  font-size: 11px;
  font-weight: 500;
  color: var(--qa-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.qa-indicator-value {
  font-size: 15px;
  font-weight: 600;
  color: var(--qa-text-primary);
  font-variant-numeric: tabular-nums;
}

.qa-indicator-right {
  display: flex;
  align-items: center;
  gap: 6px;
}

.qa-indicator-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 9px;
  background: var(--qa-accent);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.qa-tile-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(2, 1fr);
  gap: var(--qa-gap);
  padding: var(--qa-gap);
  flex: 1;
  min-height: 0;
}

.qa-tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 8px;
  background: var(--qa-bg);
  border: 1px solid var(--qa-border);
  border-radius: var(--qa-radius);
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease;
  position: relative;
  overflow: hidden;
  min-height: 0;
}

.qa-tile:hover {
  border-color: var(--qa-border-hover);
  background: var(--qa-accent-soft);
}

.qa-tile:active {
  background: var(--qa-accent-light);
}

.qa-tile-icon {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  color: var(--qa-accent);
}

.qa-tile-icon svg {
  width: 100%;
  height: 100%;
  display: block;
}

.qa-tile-body {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  text-align: center;
  min-width: 0;
}

.qa-tile-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--qa-text-primary);
  line-height: 1.3;
}

.qa-tile-status {
  font-size: 10px;
  font-weight: 400;
  color: var(--qa-text-muted);
  line-height: 1.3;
}

.qa-tile-bar {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  border-radius: 0 0 var(--qa-radius) var(--qa-radius);
}

.qa-bar-instant {
  background: var(--qa-success);
}

.qa-bar-standard {
  background: var(--qa-warning);
}

.qa-bar-live {
  background: var(--qa-live);
}

.qa-bar-neutral {
  background: var(--qa-border-hover);
}

@media (max-width: 480px) {
  .qa-tile-grid {
    grid-template-columns: repeat(2, 1fr);
    grid-template-rows: repeat(3, 1fr);
  }

  .qa-indicator-band {
    padding: 8px 12px;
  }

  .qa-indicator-value {
    font-size: 14px;
  }

  .qa-tile {
    padding: 12px 8px;
  }
}

