.ai-html-onboarding-next-hero {
  --onb-bg: var(--home-card-bg, #ffffff);
  --onb-border: var(--home-border, #e5e7eb);
  --onb-text: var(--home-text, #111827);
  --onb-text-secondary: #6b7280;
  --onb-text-muted: #9ca3af;
  --onb-primary: var(--home-primary, #0d9488);
  --onb-primary-hover: #0f766e;
  --onb-success: #059669;
  --onb-success-bg: #ecfdf5;
  --onb-warning: #d97706;
  --onb-warning-bg: #fffbeb;
  --onb-danger: #dc2626;
  --onb-danger-bg: #fef2f2;
  --onb-locked: #d1d5db;
  --onb-radius: var(--home-radius-sm, 6px);
  width: 100%;
  height: 100%;
  min-height: 180px;
  background: var(--onb-bg);
  border: 1px solid var(--onb-border);
  border-radius: var(--onb-radius);
  box-sizing: border-box;
}

.ai-html-onb-hero-inner {
  display: flex;
  height: 100%;
  min-height: 180px;
}

/* 左侧时间线 */
.ai-html-onb-timeline {
  width: 160px;
  flex-shrink: 0;
  padding: 20px 16px;
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--onb-border);
  box-sizing: border-box;
}

.ai-html-onb-step {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.ai-html-onb-node {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 2px;
}

.ai-html-onb-step-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-top: 4px;
}

.ai-html-onb-label {
  font-size: 13px;
  font-weight: 500;
  color: var(--onb-text);
  line-height: 1.3;
}

.ai-html-onb-status {
  font-size: 11px;
  line-height: 1.3;
}

.ai-html-onb-done .ai-html-onb-node {
  background: var(--onb-success-bg);
  color: var(--onb-success);
}

.ai-html-onb-done .ai-html-onb-status {
  color: var(--onb-success);
}

.ai-html-onb-current .ai-html-onb-node {
  background: #ccfbf1;
  color: var(--onb-primary);
}

.ai-html-onb-current .ai-html-onb-status {
  color: var(--onb-primary);
  font-weight: 500;
}

.ai-html-onb-pulse {
  animation: ai-html-onb-pulse-ring 2s ease-in-out infinite;
}

@keyframes ai-html-onb-pulse-ring {
  0%, 100% { box-shadow: 0 0 0 0 rgba(13, 148, 136, 0.35); }
  50% { box-shadow: 0 0 0 6px rgba(13, 148, 136, 0); }
}

.ai-html-onb-locked .ai-html-onb-node {
  background: #f3f4f6;
  color: var(--onb-locked);
}

.ai-html-onb-locked .ai-html-onb-label {
  color: var(--onb-text-muted);
}

.ai-html-onb-locked .ai-html-onb-status {
  color: var(--onb-text-muted);
}

.ai-html-onb-connector {
  width: 2px;
  height: 24px;
  margin-left: 13px;
  flex-shrink: 0;
}

.ai-html-onb-conn-done {
  background: var(--onb-success);
}

.ai-html-onb-conn-pending {
  background: repeating-linear-gradient(
    to bottom,
    var(--onb-locked) 0px,
    var(--onb-locked) 4px,
    transparent 4px,
    transparent 8px
  );
}

/* 右侧主面板 */
.ai-html-onb-current-panel {
  flex: 1;
  min-width: 0;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-sizing: border-box;
}

.ai-html-onb-panel-header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.ai-html-onb-panel-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--onb-radius);
  background: #ccfbf1;
  color: var(--onb-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.ai-html-onb-panel-title {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.ai-html-onb-panel-title strong {
  font-size: 15px;
  font-weight: 600;
  color: var(--onb-text);
  line-height: 1.4;
}

.ai-html-onb-panel-title span {
  font-size: 12px;
  color: var(--onb-text-secondary);
  line-height: 1.4;
}

.ai-html-onb-panel-body {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* KYC拒绝状态条 */
.ai-html-onb-reject-banner {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 14px;
  background: var(--onb-danger-bg);
  border: 1px solid #fecaca;
  border-radius: var(--onb-radius);
}

.ai-html-onb-reject-icon {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--onb-danger);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 1px;
}

.ai-html-onb-reject-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-width: 0;
}

.ai-html-onb-reject-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--onb-danger);
  line-height: 1.4;
}

.ai-html-onb-reject-desc {
  font-size: 11px;
  color: #991b1b;
  line-height: 1.4;
}

.ai-html-onb-retry-btn {
  padding: 6px 14px;
  font-size: 12px;
  font-weight: 500;
  color: var(--onb-danger);
  background: #fff;
  border: 1px solid var(--onb-danger);
  border-radius: var(--onb-radius);
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
}

.ai-html-onb-retry-btn:hover {
  background: var(--onb-danger);
  color: #fff;
}

/* 账户选项 */
.ai-html-onb-account-options {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ai-html-onb-option-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid #f3f4f6;
}

.ai-html-onb-option-row:last-child {
  border-bottom: none;
}

.ai-html-onb-opt-label {
  font-size: 12px;
  color: var(--onb-text-secondary);
}

.ai-html-onb-opt-value {
  font-size: 12px;
  font-weight: 500;
  color: var(--onb-text);
}

/* 操作坞 */
.ai-html-onb-panel-actions {
  display: flex;
  gap: 10px;
  margin-top: auto;
  padding-top: 4px;
}

.ai-html-onb-btn {
  padding: 9px 20px;
  font-size: 13px;
  font-weight: 500;
  border-radius: var(--onb-radius);
  cursor: pointer;
  border: none;
  white-space: nowrap;
}

.ai-html-onb-btn-primary {
  background: var(--onb-primary);
  color: #fff;
}

.ai-html-onb-btn-primary:hover {
  background: var(--onb-primary-hover);
}

.ai-html-onb-btn-ghost {
  background: transparent;
  color: var(--onb-text-secondary);
  border: 1px solid var(--onb-border);
}

.ai-html-onb-btn-ghost:hover {
  background: #f9fafb;
  color: var(--onb-text);
}

/* 响应式 */
@media (max-width: 720px) {
  .ai-html-onb-hero-inner {
    flex-direction: column;
  }

  .ai-html-onb-timeline {
    width: 100%;
    flex-direction: row;
    padding: 16px;
    border-right: none;
    border-bottom: 1px solid var(--onb-border);
    gap: 0;
  }

  .ai-html-onb-step {
    flex: 1;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 6px;
  }

  .ai-html-onb-step-info {
    padding-top: 0;
  }

  .ai-html-onb-connector {
    width: 24px;
    height: 2px;
    margin-left: 0;
    align-self: center;
    margin-top: 14px;
  }

  .ai-html-onb-conn-pending {
    background: repeating-linear-gradient(
      to right,
      var(--onb-locked) 0px,
      var(--onb-locked) 4px,
      transparent 4px,
      transparent 8px
    );
  }

  .ai-html-onb-current-panel {
    padding: 16px;
  }

  .ai-html-onb-panel-actions {
    flex-direction: column;
  }

  .ai-html-onb-btn {
    width: 100%;
    text-align: center;
  }
}

/* 隐藏非当前状态的拒绝横幅 */
.ai-html-onb-reject-banner[data-kyc="verified"],
.ai-html-onb-reject-banner[data-kyc="pending"] {
  display: none;
}

