  border-bottom: 1px solid var(--faq-border);
  flex-shrink: 0;
}

.ai-html-faq-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.ai-html-faq-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--faq-text);
  margin: 0;
  line-height: 1.3;
}

.ai-html-faq-viewall {
  font-size: 12px;
  color: var(--faq-primary);
  text-decoration: none;
  font-weight: 500;
  white-space: nowrap;
}

.ai-html-faq-viewall:hover {
  text-decoration: underline;
