.ai-html-faq-indicator {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.ai-html-faq-count {
  font-size: 12px;
  color: var(--faq-text-secondary);
  font-weight: 500;
  white-space: nowrap;
}

.ai-html-faq-pills {
  display: flex;
  gap: 6px;
}

.ai-html-faq-pill {
  font-size: 11px;
  padding: 3px 10px;
  border-radius: 4px;
  background: #f3f4f6;
  color: var(--faq-text-secondary);
  cursor: pointer;
  transition: all 0.15s ease;
  border: none;
  font-weight: 500;
}

.ai-html-faq-pill--active,
.ai-html-faq-pill:hover {
  background: var(--faq-primary-light);
  color: var(--faq-primary);
}

.ai-html-faq-body {
  display: flex;
  flex: 1;
  gap: var(--faq-gap);
  padding: var(--faq-gap);
  overflow: auto;
  min-height: 0;
}

.ai-html-faq-col {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--faq-gap);
  min-width: 0;
}

.ai-html-faq-item {
  border: 1px solid var(--faq-border);
  border-radius: var(--faq-radius);
  overflow: hidden;
  flex-shrink: 0;
}

.ai-html-faq-q {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 12px;
  background: none;
  border: none;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
  color: var(--faq-text);
  text-align: left;
  line-height: 1.4;
  transition: background 0.15s ease;
}

.ai-html-faq-q:hover {
  background: #f9fafb;
}

.ai-html-faq-q[aria-expanded="true"] {
  background: var(--faq-primary-light);
  color: var(--faq-primary);
}

.ai-html-faq-q[aria-expanded="true"] .ai-html-faq-toggle {
  transform: rotate(45deg);
}

.ai-html-faq-qtext {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding-right: 8px;
}

.ai-html-faq-toggle {
  font-size: 16px;
  font-weight: 400;
  color: var(--faq-text-secondary);
  transition: transform 0.2s ease, color 0.15s ease;
  flex-shrink: 0;
  width: 20px;
  text-align: center;
}

.ai-html-faq-q[aria-expanded="true"] .ai-html-faq-toggle {
  color: var(--faq-primary);
}

.ai-html-faq-a {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.25s ease, padding 0.25s ease;
  background: var(--faq-bg);
}

.ai-html-faq-a p {
  margin: 0;
  padding: 0 12px 12px;
  font-size: 12px;
  line-height: 1.6;
  color: var(--faq-text-secondary);
}

.ai-html-faq-q[aria-expanded="true"] + .ai-html-faq-a {
  max-height: 120px;
  padding-top: 2px;
}

@media (max-width: 640px) {
  .ai-html-faq-body {
    flex-direction: column;
  }

  .ai-html-faq-indicator {
    gap: 8px;
  }

  .ai-html-faq-qtext {
    white-space: normal;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
  }
}

