.ai-html-signals-curator {
  --sig-bg: var(--home-card-bg, #ffffff);
  --sig-text: var(--home-text, #1e293b);
  --sig-text-secondary: #64748b;
  --sig-border: var(--home-border, #e2e8f0);
  --sig-primary: var(--home-primary, #0d9488);
  --sig-primary-light: #f0fdfa;
  --sig-radius: 6px;
  --sig-green: #059669;
  --sig-red: #dc2626;
  --sig-amber: #d97706;
  --sig-blue: #0369a1;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--sig-bg);
  border: 1px solid var(--sig-border);
  border-radius: var(--sig-radius);
  padding: 20px;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.ai-html-signals-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 16px;
  flex-shrink: 0;
}

.ai-html-signals-title {
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.ai-html-signals-title h3 {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--sig-text);
  line-height: 1.3;
}

.ai-html-signals-live {
  font-size: 12px;
  color: var(--sig-text-secondary);
  font-weight: 400;
}

.ai-html-signals-more {
  font-size: 13px;
  color: var(--sig-primary);
  text-decoration: none;
  font-weight: 500;
  white-space: nowrap;
}

.ai-html-signals-more:hover {
  text-decoration: underline;
}

.ai-html-signals-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  flex: 1;
  min-height: 0;
}

.ai-html-signal-card {
  border: 1px solid var(--sig-border);
  border-radius: var(--sig-radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--sig-bg);
  transition: border-color 0.15s ease;
}

.ai-html-signal-card:hover {
  border-color: #cbd5e1;
}

.ai-html-signal-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.ai-html-signal-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--sig-text);
  line-height: 1.3;
}

.ai-html-risk-tag {
  font-size: 11px;
  font-weight: 500;
  padding: 2px 8px;
  border-radius: 4px;
  white-space: nowrap;
  flex-shrink: 0;
}

.ai-html-risk-low {
  background: #ecfdf5;
  color: var(--sig-green);
}

.ai-html-risk-mid {
  background: #fffbeb;
  color: var(--sig-amber);
}

.ai-html-risk-high {
  background: #fef2f2;
  color: var(--sig-red);
}

.ai-html-signal-metrics {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ai-html-metric {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.ai-html-metric-label {
  font-size: 12px;
  color: var(--sig-text-secondary);
  font-weight: 400;
}

.ai-html-metric-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--sig-text);
  font-variant-numeric: tabular-nums;
}

.ai-html-positive {
  color: var(--sig-green);
}

.ai-html-negative {
  color: var(--sig-red);
}

.ai-html-trend-box {
  border: 1px solid var(--sig-border);
  border-radius: var(--sig-radius);
  padding: 10px 12px;
  background: #f8fafc;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ai-html-trend-header {
  display: flex;
  gap: 12px;
  font-size: 11px;
  font-weight: 500;
  color: var(--sig-text-secondary);
}

.ai-html-trend-header span {
  cursor: pointer;
  padding-bottom: 2px;
  border-bottom: 1.5px solid transparent;
}

.ai-html-trend-active {
  color: var(--sig-primary) !important;
  border-bottom-color: var(--sig-primary) !important;
}

.ai-html-trend-canvas {
  flex: 1;
  min-height: 0;
  position: relative;
}

.ai-html-trend-canvas svg {
  width: 100%;
  height: 100%;
  display: block;
}

.ai-html-btn {
  width: 100%;
  padding: 8px 0;
  border-radius: var(--sig-radius);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  border: none;
  text-align: center;
  transition: all 0.15s ease;
  flex-shrink: 0;
}

.ai-html-btn-primary {
  background: var(--sig-primary);
  color: #fff;
}

.ai-html-btn-primary:hover {
  background: #0f766e;
}

.ai-html-btn-ghost {
  background: transparent;
  color: var(--sig-text-secondary);
  border: 1px solid var(--sig-border);
}

.ai-html-btn-ghost:hover {
  background: #f1f5f9;
}

@media (max-width: 768px) {
  .ai-html-signals-grid {
    grid-template-columns: 1fr;
  }
  .ai-html-signals-curator {
    padding: 16px;
  }
  .ai-html-signal-card {
    padding: 14px;
  }
}

@media (min-width: 769px) and (max-width: 1024px) {
  .ai-html-signals-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

