  --wpr-border: var(--home-border, #e8ecf1);
  --wpr-text: var(--home-text, #1a2332);
  --wpr-text-secondary: #6b7b8f;
  --wpr-primary: var(--home-primary, #2563eb);
  --wpr-primary-hover: #1d4ed8;
  --wpr-surface: #f6f8fb;
  --wpr-radius: var(--home-radius-sm, 6px);

  background: var(--wpr-bg);
  border: 1px solid var(--wpr-border);
  border-radius: var(--wpr-radius);
  padding: 20px 24px 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-height: 0;
  box-sizing: border-box;
}

.ai-html-welcome-inner {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.ai-html-welcome-left {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  flex: 1 1 280px;
}

.ai-html-greeting-block {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
}

.ai-html-client-name {
  font-size: 20px;
  font-weight: 600;
  color: var(--wpr-text);
  margin: 0;
  line-height: 1.3;
  letter-spacing: -0.01em;
}

.ai-html-greeting-text {
  font-size: 13px;
  color: var(--wpr-text-secondary);
  font-weight: 400;
  line-height: 1.4;
}

.ai-html-market-line {
  font-size: 12px;
  color: var(--wpr-text-secondary);
  margin: 0;
  line-height: 1.5;
  max-width: 420px;
}

.ai-html-welcome-right {
  flex: 0 1 auto;
  min-width: 0;
}

.ai-html-kpi-ribbon {
  display: flex;
  align-items: center;
  gap: 0;
  background: var(--wpr-surface);
  border-radius: var(--wpr-radius);
  padding: 12px 16px;
}

.ai-html-kpi-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 0 16px;
  min-width: 0;
}

.ai-html-kpi-item:first-child {
  padding-left: 0;
}

.ai-html-kpi-item:last-child {
  padding-right: 0;
}

.ai-html-kpi-label {
  font-size: 11px;
  color: var(--wpr-text-secondary);
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
}

.ai-html-kpi-value {
  font-size: 16px;
  font-weight: 600;
  color: var(--wpr-text);
  line-height: 1.3;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.ai-html-kpi-divider {
  width: 1px;
  height: 28px;
  background: var(--wpr-border);
  flex-shrink: 0;
}

.ai-html-action-dock {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  padding-top: 4px;
  border-top: 1px solid var(--wpr-border);
}

.ai-html-btn {
  font-size: 13px;
  font-weight: 500;
  padding: 7px 18px;
  border-radius: var(--wpr-radius);
  border: 1px solid transparent;
  cursor: pointer;
  line-height: 1.4;
  transition: background-color 0.15s, border-color 0.15s;
