}

.ai-html-btn-primary:hover {
  background: var(--wpr-primary-hover);
  border-color: var(--wpr-primary-hover);
}

.ai-html-btn-secondary {
  background: var(--wpr-bg);
  color: var(--wpr-text);
  border-color: var(--wpr-border);
}

.ai-html-btn-secondary:hover {
  background: var(--wpr-surface);
  border-color: #d1d5db;
}

@media (max-width: 720px) {
