    padding: 16px;
    gap: 14px;
  }

  .ai-html-welcome-inner {
    flex-direction: column;
    gap: 16px;
  }

  .ai-html-welcome-left {
    flex: 1 1 auto;
  }

  .ai-html-kpi-ribbon {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
    padding: 12px;
    width: 100%;
  }

  .ai-html-kpi-item {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    padding: 0;
    gap: 12px;
  }

  .ai-html-kpi-divider {
    display: none;
  }

  .ai-html-kpi-value {
    font-size: 15px;
  }

  .ai-html-action-dock {
    gap: 6px;
  }

  .ai-html-btn {
    flex: 1 1 auto;
    padding: 8px 14px;
    font-size: 12px;
  }
