.qa-tileboard {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  background: #fff;
  border-radius: 6px;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.qa-indicator-band {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 10px;
  border-bottom: 1px solid #e8ecf1;
  flex-shrink: 0;
}

.qa-metric {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.qa-metric--right {
  justify-content: flex-end;
}

.qa-metric-label {
  font-size: 12px;
  color: #6b7b8f;
  font-weight: 400;
  line-height: 16px;
}

.qa-metric-value {
  font-size: 15px;
  font-weight: 600;
  color: #0d1f36;
  line-height: 20px;
  letter-spacing: -0.2px;
}

.qa-metric-value--alert {
  color: #0a8f6c;
}

.qa-tile-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(2, 1fr);
  gap: 8px;
  padding: 12px 16px 16px;
  flex: 1;
  min-height: 0;
}

.qa-tile {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
