.ai-html-asset-compact-desk {
  --acd-bg: var(--home-card-bg, #0f172a);
  --acd-border: var(--home-border, rgba(148, 163, 184, 0.12));
  --acd-text-primary: var(--home-text, #f1f5f9);
  --acd-text-secondary: var(--home-text-secondary, #94a3b8);
  --acd-text-tertiary: var(--home-text-tertiary, #64748b);
  --acd-accent: var(--home-primary, #10b981);
  --acd-accent-dim: rgba(16, 185, 129, 0.15);
  --acd-surface: rgba(148, 163, 184, 0.06);
  --acd-surface-hover: rgba(148, 163, 184, 0.10);
  --acd-radius: 6px;

  width: 100%;
  height: 100%;
  min-height: 0;
  background: var(--acd-bg);
  border: 1px solid var(--acd-border);
  border-radius: var(--home-radius-sm, 8px);
  box-sizing: border-box;
  overflow: hidden;
}

.ai-html-acd-inner {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 16px 20px;
  gap: 12px;
  box-sizing: border-box;
}

.ai-html-acd-hero {
  flex-shrink: 0;
}

.ai-html-acd-hero-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 500;
  color: var(--acd-text-secondary);
  line-height: 1;
  margin-bottom: 6px;
}

.ai-html-acd-pulse {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--acd-accent);
  animation: ai-html-acd-pulse 2s ease-in-out infinite;
}

@keyframes ai-html-acd-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

.ai-html-acd-currency {
  padding: 2px 6px;
  background: var(--acd-accent-dim);
  color: var(--acd-accent);
  font-size: 10px;
  font-weight: 600;
  border-radius: 3px;
  letter-spacing: 0.02em;
}

.ai-html-acd-hero-value {
  font-size: 28px;
  font-weight: 700;
  color: var(--acd-text-primary);
  line-height: 1.15;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.ai-html-acd-metrics {
  display: flex;
  flex: 1;
  gap: 8px;
  min-height: 0;
}

.ai-html-acd-metric {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 10px 12px;
  background: var(--acd-surface);
  border-radius: var(--acd-radius);
  border: 1px solid transparent;
  transition: background 0.15s ease, border-color 0.15s ease;
  min-width: 0;
}

.ai-html-acd-metric:hover {
  background: var(--acd-surface-hover);
  border-color: var(--acd-border);
}

.ai-html-acd-metric-label {
  font-size: 11px;
  font-weight: 500;
  color: var(--acd-text-tertiary);
  line-height: 1.3;
  margin-bottom: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ai-html-acd-metric-value {
  font-size: 15px;
  font-weight: 600;
  color: var(--acd-text-primary);
  line-height: 1.25;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ai-html-acd-metric-detail {
  font-size: 10px;
  color: var(--acd-text-tertiary);
  line-height: 1.3;
  margin-top: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ai-html-acd-actions {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}

.ai-html-acd-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 9px 0;
  border-radius: var(--acd-radius);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.15s ease;
  line-height: 1;
}

.ai-html-acd-btn-primary {
  background: var(--acd-accent);
  color: #fff;
}

.ai-html-acd-btn-primary:hover {
  filter: brightness(1.08);
}

.ai-html-acd-btn-secondary {
  background: var(--acd-surface);
  color: var(--acd-text-primary);
  border: 1px solid var(--acd-border);
}

.ai-html-acd-btn-secondary:hover {
  background: var(--acd-surface-hover);
}

.ai-html-acd-btn-icon {
  font-size: 13px;
  font-weight: 500;
  line-height: 1;
}

@media (max-width: 720px) {
  .ai-html-acd-inner {
    padding: 14px 16px;
    gap: 10px;
  }

  .ai-html-acd-hero-value {
    font-size: 24px;
  }

  .ai-html-acd-metrics {
    flex-direction: column;
    gap: 6px;
  }

  .ai-html-acd-metric {
    flex-direction: row;
    align-items: center;
    gap: 12px;
    padding: 10px 12px;
    flex: none;
  }

  .ai-html-acd-metric-label {
    flex-shrink: 0;
    width: 80px;
    margin-bottom: 0;
  }

  .ai-html-acd-metric-value {
    flex: 1;
    text-align: right;
  }

  .ai-html-acd-metric-detail {
    display: none;
  }

  .ai-html-acd-actions {
    gap: 6px;
  }

  .ai-html-acd-btn {
    padding: 11px 0;
  }
}

@media (max-width: 480px) {
  .ai-html-acd-hero-value {
    font-size: 22px;
  }

  .ai-html-acd-metric-label {
    width: 70px;
    font-size: 10px;
  }

  .ai-html-acd-metric-value {
    font-size: 13px;
  }
}

.ao-onboarding-desk {
  --ao-blue-50: #f0f5ff;
  --ao-blue-100: #dbe4f5;
  --ao-blue-500: #2563eb;
  --ao-blue-600: #1d4ed8;
  --ao-blue-700: #1e40af;
  --ao-slate-50: #f8fafc;
  --ao-slate-100: #f1f5f9;
  --ao-slate-200: #e2e8f0;
  --ao-slate-400: #94a3b8;
  --ao-slate-500: #64748b;
  --ao-slate-600: #475569;
  --ao-slate-700: #334155;
  --ao-slate-800: #1e293b;
  --ao-slate-900: #0f172a;
  --ao-emerald-500: #10b981;
  --ao-amber-500: #f59e0b;
  --ao-rose-500: #f43f5e;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: #fff;
  border-radius: 8px;
  border: 1px solid var(--ao-slate-200);
  padding: 24px;
  width: 100%;
  box-sizing: border-box;
}

.ao-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 20px;
}

.ao-hero-left {
  flex: 1;
  min-width: 0;
}

.ao-status-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

.ao-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ao-amber-500);
  position: relative;
  flex-shrink: 0;
}

.ao-pulse::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  border: 2px solid var(--ao-amber-500);
  opacity: 0.4;
  animation: ao-pulse-ring 2s ease-out infinite;
}

@keyframes ao-pulse-ring {
  0% { transform: scale(1); opacity: 0.4; }
  100% { transform: scale(2); opacity: 0; }
}

.ao-status-tag {
  font-size: 12px;
  font-weight: 500;
  padding: 3px 10px;
  border-radius: 4px;
  background: var(--ao-amber-500);
  color: #fff;
  letter-spacing: 0.02em;
}

.ao-status-tag[data-status="pending"] {
  background: var(--ao-amber-500);
}

.ao-status-tag[data-status="active"] {
  background: var(--ao-emerald-500);
}

.ao-status-tag[data-status="inactive"] {
  background: var(--ao-slate-400);
}

.ao-total {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0 8px;
}

.ao-total-label {
  font-size: 13px;
  color: var(--ao-slate-500);
  font-weight: 400;
  margin-right: 4px;
}

.ao-total-currency {
  font-size: 13px;
  color: var(--ao-slate-400);
  font-weight: 500;
}

.ao-total-value {
  font-size: 32px;
  font-weight: 700;
  color: var(--ao-slate-900);
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.ao-hero-right {
  flex-shrink: 0;
  padding-top: 4px;
}

.ao-progress-track {
  display: flex;
  align-items: center;
  gap: 0;
}

.ao-progress-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.ao-step-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--ao-slate-200);
  border: 2px solid var(--ao-slate-200);
  transition: all 0.2s ease;
}

.ao-progress-step.completed .ao-step-dot {
  background: var(--ao-emerald-500);
  border-color: var(--ao-emerald-500);
}

.ao-progress-step.active .ao-step-dot {
  background: #fff;
  border-color: var(--ao-blue-500);
  box-shadow: 0 0 0 3px var(--ao-blue-50);
}

.ao-step-label {
  font-size: 11px;
  color: var(--ao-slate-400);
  font-weight: 500;
  white-space: nowrap;
}

.ao-progress-step.completed .ao-step-label {
  color: var(--ao-emerald-500);
}

.ao-progress-step.active .ao-step-label {
  color: var(--ao-blue-600);
  font-weight: 600;
}

.ao-progress-line {
  width: 32px;
  height: 2px;
  background: var(--ao-slate-200);
  margin: 0 6px;
  margin-bottom: 17px;
  flex-shrink: 0;
}

.ao-progress-line.active {
  background: var(--ao-blue-200);
}

.ao-metrics {
  display: flex;
  gap: 12px;
  margin-bottom: 16px;
}

.ao-metric-card {
  flex: 1;
  min-width: 0;
  position: relative;
  background: var(--ao-slate-50);
  border-radius: 6px;
  overflow: hidden;
}

.ao-metric-border {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
}

.ao-metric-card.wallet .ao-metric-border {
  background: var(--ao-blue-500);
}

.ao-metric-card.trading .ao-metric-border {
  background: var(--ao-emerald-500);
}

.ao-metric-card.credit .ao-metric-border {
  background: var(--ao-slate-400);
}

.ao-metric-inner {
  padding: 14px 16px;
  padding-left: 18px;
}

.ao-metric-label {
  display: block;
  font-size: 12px;
  color: var(--ao-slate-500);
  font-weight: 500;
  margin-bottom: 6px;
  letter-spacing: 0.01em;
}

.ao-metric-value {
  display: block;
  font-size: 18px;
  font-weight: 700;
  color: var(--ao-slate-800);
  line-height: 1.2;
  margin-bottom: 5px;
  letter-spacing: -0.01em;
}

.ao-metric-meta {
  display: block;
  font-size: 11px;
  color: var(--ao-slate-400);
  font-weight: 400;
}

.ao-action-dock {
  display: flex;
  gap: 10px;
}

.ao-action-dock.hidden {
  display: none;
}

.ao-btn {
  flex: 1;
  padding: 10px 20px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.15s ease;
  text-align: center;
}

.ao-btn-primary {
  background: var(--ao-blue-600);
  color: #fff;
}

.ao-btn-primary:hover {
  background: var(--ao-blue-700);
}

.ao-btn-secondary {
  background: var(--ao-slate-100);
  color: var(--ao-slate-700);
  border: 1px solid var(--ao-slate-200);
}

.ao-btn-secondary:hover {
  background: var(--ao-slate-200);
}

@media (max-width: 720px) {
  .ao-onboarding-desk {
    padding: 20px;
  }

  .ao-hero {
    flex-direction: column;
    gap: 16px;
  }

  .ao-hero-right {
    width: 100%;
    padding-top: 0;
  }

  .ao-progress-track {
    justify-content: flex-start;
  }

  .ao-progress-line {
    flex: 1;
    max-width: 48px;
  }

  .ao-total-value {
    font-size: 28px;
  }

  .ao-metrics {
    flex-direction: column;
    gap: 8px;
  }

  .ao-metric-inner {
    padding: 12px 14px;
    padding-left: 16px;
  }

  .ao-metric-value {
    font-size: 16px;
  }

  .ao-action-dock {
    flex-direction: column;
  }

  .ao-btn {
    width: 100%;
  }
}

@media (max-width: 480px) {
  .ao-onboarding-desk {
    padding: 16px;
  }

  .ao-total-value {
    font-size: 24px;
  }

  .ao-step-label {
    font-size: 10px;
  }

  .ao-progress-line {
    max-width: 32px;
  }
}

