  letter-spacing: 0.3px;
}

.ai-ta-metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px 12px;
  margin-bottom: 10px;
}

.ai-ta-metric {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.ai-ta-metric-label {
  font-size: 11px;
  color: var(--ta-text-tertiary);
  line-height: 1.3;
}

.ai-ta-metric-value {
  font-size: 12px;
  font-weight: 500;
  color: var(--ta-text);
  line-height: 1.4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ai-ta-metric-value--strong {
  font-weight: 600;
}

.ai-ta-health {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  padding: 6px 8px;
  background: #f9fafb;
  border-radius: var(--ta-radius-sm);
}

.ai-ta-health-bar {
  flex: 1;
  height: 4px;
  border-radius: 2px;
  background: #e5e7eb;
  position: relative;
  overflow: hidden;
}

.ai-ta-health-bar::after {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  border-radius: 2px;
}

.ai-ta-health-bar--safe::after {
  width: 85%;
  background: var(--ta-primary);
}

.ai-ta-health-bar--warning::after {
  width: 45%;
  background: var(--ta-warning);
}

.ai-ta-health-bar--danger::after {
  width: 15%;
  background: var(--ta-danger);
}

.ai-ta-health-label {
  font-size: 11px;
  font-weight: 500;
  color: var(--ta-primary);
  flex-shrink: 0;
}

.ai-ta-actions {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.ai-ta-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 6px 14px;
  border-radius: var(--ta-radius-sm);
  font-size: 12px;
  font-weight: 500;
  line-height: 1.4;
  cursor: pointer;
  border: none;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.ai-ta-btn--primary {
  background: var(--ta-primary);
  color: #ffffff;
}

.ai-ta-btn--primary:hover {
  background: var(--ta-primary-hover);
}

.ai-ta-btn--secondary {
  background: transparent;
  color: var(--ta-text-secondary);
  border: 1px solid var(--ta-border);
}

.ai-ta-btn--secondary:hover {
  background: #f9fafb;
  border-color: #d1d5db;
  color: var(--ta-text);
}

@media (max-width: 768px) {
  .ai-ta-columns {
    grid-template-columns: 1fr;
  }

  .ai-ta-metrics {
    grid-template-columns: repeat(2, 1fr);
  }

  .ai-ta-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .ai-ta-row-main {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .ai-html-trading-accounts-dual {
    padding: 12px;
  }

  .ai-ta-metrics {
    grid-template-columns: repeat(2, 1fr);
    gap: 6px 8px;
  }

  .ai-ta-btn {
    padding: 5px 10px;
    font-size: 11px;
  }
}

