.promo-deposit-ladder {
  --promo-bg: #0f172a;
  --promo-surface: rgba(255,255,255,0.06);
  --promo-border: rgba(255,255,255,0.08);
  --promo-text: #f8fafc;
  --promo-muted: #94a3b8;
  --promo-accent: #3b82f6;
  --promo-accent-dim: rgba(59,130,246,0.15);
  --promo-success: #10b981;
  --promo-success-dim: rgba(16,185,129,0.15);
  --promo-warn: #f59e0b;
  --radius: 6px;
  display: flex;
  width: 100%;
  min-height: 180px;
  background: var(--promo-bg);
  border-radius: 8px;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--promo-text);
}

.promo-deposit-ladder .promo-main {
  flex: 1;
  padding: 24px 28px;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.promo-deposit-ladder .promo-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

.promo-deposit-ladder .promo-badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  background: var(--promo-success-dim);
  color: var(--promo-success);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  border-radius: var(--radius);
  text-transform: uppercase;
}

.promo-deposit-ladder .promo-period {
  font-size: 12px;
  color: var(--promo-muted);
  letter-spacing: 0.01em;
}

.promo-deposit-ladder .promo-title {
  font-size: 20px;
  font-weight: 700;
  line-height: 1.3;
  margin: 0 0 6px 0;
  letter-spacing: -0.01em;
}

.promo-deposit-ladder .promo-sub {
  font-size: 13px;
  color: var(--promo-muted);
  line-height: 1.5;
  margin: 0 0 20px 0;
}

.promo-deposit-ladder .ladder-progress {
  margin-bottom: 16px;
}

.promo-deposit-ladder .ladder-track {
  position: relative;
  height: 4px;
  background: var(--promo-surface);
  border-radius: 2px;
  margin-bottom: 12px;
}

.promo-deposit-ladder .ladder-fill {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  background: linear-gradient(90deg, var(--promo-success), var(--promo-accent));
  border-radius: 2px;
  transition: width 0.4s ease;
}

.promo-deposit-ladder .ladder-marks {
  position: absolute;
  inset: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 0;
}

.promo-deposit-ladder .mark {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--promo-bg);
  border: 2px solid var(--promo-border);
  box-shadow: 0 0 0 2px var(--promo-bg);
  transition: all 0.3s ease;
}

.promo-deposit-ladder .mark.done {
  background: var(--promo-success);
  border-color: var(--promo-success);
}

.promo-deposit-ladder .mark.active {
  background: var(--promo-bg);
  border-color: var(--promo-accent);
  box-shadow: 0 0 0 2px var(--promo-bg), 0 0 0 4px var(--promo-accent-dim);
}

.promo-deposit-ladder .ladder-labels {
  display: flex;
  justify-content: space-between;
}

.promo-deposit-ladder .label {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 60px;
}

.promo-deposit-ladder .label-tier {
  font-size: 12px;
  font-weight: 600;
  color: var(--promo-muted);
}

.promo-deposit-ladder .label.active .label-tier {
  color: var(--promo-accent);
}

.promo-deposit-ladder .label-reward {
  font-size: 14px;
  font-weight: 700;
  color: var(--promo-text);
}

.promo-deposit-ladder .label.done .label-reward {
  color: var(--promo-success);
}

.promo-deposit-ladder .promo-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--promo-muted);
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--promo-border);
}

.promo-deposit-ladder .promo-dock {
  width: 280px;
  padding: 24px;
  background: var(--promo-surface);
  border-left: 1px solid var(--promo-border);
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex-shrink: 0;
}

.promo-deposit-ladder .dock-status {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--promo-border);
  margin-bottom: 4px;
}

.promo-deposit-ladder .status-item {
  display: flex;
  align-items: center;
  gap: 6px;
}

.promo-deposit-ladder .status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--promo-success);
}

.promo-deposit-ladder .status-dot.pulse {
  animation: promo-pulse 2s ease-in-out infinite;
}

@keyframes promo-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.promo-deposit-ladder .status-text {
  font-size: 12px;
  font-weight: 500;
  color: var(--promo-success);
}

.promo-deposit-ladder .status-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--promo-text);
}

.promo-deposit-ladder .status-label {
  font-size: 11px;
  color: var(--promo-muted);
  margin-left: 4px;
}

.promo-deposit-ladder .btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 16px;
  border-radius: var(--radius);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.15s ease;
  width: 100%;
}

.promo-deposit-ladder .btn-primary {
  background: var(--promo-accent);
  color: #fff;
}

.promo-deposit-ladder .btn-primary:hover {
  background: #2563eb;
}

.promo-deposit-ladder .btn-secondary {
  background: transparent;
  color: var(--promo-muted);
  border: 1px solid var(--promo-border);
}

.promo-deposit-ladder .btn-secondary:hover {
  color: var(--promo-text);
  border-color: var(--promo-muted);
}

.promo-deposit-ladder .dock-terms {
  font-size: 11px;
  color: var(--promo-muted);
  line-height: 1.6;
  margin-top: 4px;
}

@media (max-width: 720px) {
  .promo-deposit-ladder {
    flex-direction: column;
  }
  .promo-deposit-ladder .promo-dock {
    width: 100%;
    border-left: none;
    border-top: 1px solid var(--promo-border);
    padding: 20px;
  }
  .promo-deposit-ladder .promo-main {
    padding: 20px;
  }
  .promo-deposit-ladder .ladder-labels {
    gap: 16px;
  }
  .promo-deposit-ladder .label {
    min-width: 0;
    flex: 1;
  }
