.ao-ticker-strip {
  --ao-bg: #ffffff;
  --ao-text-primary: #0f172a;
  --ao-text-secondary: #64748b;
  --ao-text-tertiary: #94a3b8;
  --ao-border: #e2e8f0;
  --ao-accent: #2563eb;
  --ao-accent-light: #dbeafe;
  --ao-credit: #059669;
  --ao-credit-bg: #d1fae5;
  --ao-radius: 6px;
  --ao-gap: 16px;

  width: 100%;
  background: var(--ao-bg);
  border: 1px solid var(--ao-border);
  border-radius: var(--ao-radius);
  padding: 20px 24px;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.ao-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ao-gap);
}

.ao-header-left {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.ao-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ao-accent);
  position: relative;
  flex-shrink: 0;
}

.ao-pulse::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 2px solid var(--ao-accent-light);
  animation: ao-pulse-ring 2s ease-out infinite;
}

@keyframes ao-pulse-ring {
  0% { transform: scale(0.8); opacity: 1; }
  100% { transform: scale(1.6); opacity: 0; }
}

.ao-currency {
  font-size: 12px;
  font-weight: 600;
  color: var(--ao-accent);
  background: var(--ao-accent-light);
  padding: 2px 8px;
  border-radius: 4px;
  letter-spacing: 0.02em;
}

.ao-total-label {
  font-size: 13px;
  color: var(--ao-text-secondary);
  font-weight: 500;
}

.ao-header-right {
  min-width: 0;
  text-align: right;
}

.ao-total-value {
  font-size: 28px;
  font-weight: 700;
  color: var(--ao-text-primary);
  letter-spacing: -0.02em;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}

.ao-divider {
  height: 1px;
  background: var(--ao-border);
  margin: 16px 0;
}

.ao-metrics {
  display: flex;
  align-items: stretch;
  gap: 0;
}

.ao-metric {
  flex: 1;
  min-width: 0;
  padding: 0 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ao-metric:first-child {
  padding-left: 0;
}

.ao-metric:last-child {
  padding-right: 0;
}

.ao-metric-sep {
  width: 1px;
  flex-shrink: 0;
  background: var(--ao-border);
  margin: 4px 0;
}

.ao-metric-top {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ao-metric-label {
  font-size: 12px;
  color: var(--ao-text-secondary);
  font-weight: 500;
  white-space: nowrap;
}

.ao-metric-value {
  font-size: 18px;
  font-weight: 600;
  color: var(--ao-text-primary);
  font-variant-numeric: tabular-nums;
  line-height: 1.3;
}

.ao-metric-value.ao-credit {
  color: var(--ao-credit);
}

.ao-metric-bottom {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  min-height: 22px;
}

.ao-breakdown-tag {
  font-size: 11px;
  color: var(--ao-text-tertiary);
  background: #f1f5f9;
  padding: 2px 8px;
  border-radius: 4px;
  font-weight: 500;
  white-space: nowrap;
}

.ao-breakdown-count {
  font-size: 11px;
  color: var(--ao-text-tertiary);
  font-weight: 500;
  margin-left: auto;
  white-space: nowrap;
}

@media (max-width: 720px) {
  .ao-ticker-strip {
    padding: 16px;
  }

  .ao-header {
    flex-wrap: wrap;
    gap: 8px;
  }

  .ao-header-right {
    width: 100%;
    text-align: left;
  }

  .ao-total-value {
    font-size: 24px;
  }

  .ao-metrics {
    flex-direction: column;
    gap: 12px;
  }

  .ao-metric {
    padding: 0;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
  }

  .ao-metric-sep {
    display: none;
  }

  .ao-metric-top {
    flex-direction: row;
    align-items: baseline;
    gap: 8px;
  }

  .ao-metric-bottom {
    justify-content: flex-end;
    margin-left: auto;
  }

  .ao-breakdown-count {
    margin-left: 0;
  }
}

@media (max-width: 480px) {
  .ao-metric {
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
  }

  .ao-metric-top {
    width: 100%;
    justify-content: space-between;
  }

  .ao-metric-bottom {
    width: 100%;
    justify-content: flex-start;
  }
}

