  min-height: 0;
}

.ap-chart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
  flex-shrink: 0;
}

.ap-chart-title {
  font-size: 13px;
  font-weight: 600;
  color: #374151;
}

.ap-chart-tabs {
  display: flex;
  gap: 2px;
  background: #f3f4f6;
  border-radius: 4px;
  padding: 2px;
}

.ap-tab {
  padding: 4px 12px;
  font-size: 11px;
