  border: none;
  border-radius: 3px;
  cursor: pointer;
  line-height: 1.4;
}

.ap-tab--active {
  background: #fff;
  color: #111827;
  box-shadow: 0 1px 2px rgba(0,0,0,0.05);
}

.ap-chart-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  position: relative;
}

.ap-chart-svg {
  flex: 1;
  width: 100%;
  min-height: 0;
}

.ap-chart-axis {
  display: flex;
  justify-content: space-between;
  padding-top: 8px;
  font-size: 10px;
  color: #9ca3af;
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}

.ap-dock {
  grid-column: 1 / -1;
  display: flex;
  gap: 8px;
  padding: 12px 16px;
  border-top: 1px solid #f3f4f6;
  background: #fafafa;
}

.ap-dock-btn {
  padding: 7px 16px;
  font-size: 12px;
