  .ap-left {
    grid-row: 1;
    border-right: none;
    border-bottom: 1px solid #f3f4f6;
    padding: 16px;
  }

  .ap-metric-band {
    flex-direction: row;
    flex-wrap: wrap;
    gap: 0;
  }

  .ap-metric {
    flex: 1 1 50%;
    border-top: none;
    border-bottom: 1px solid #f3f4f6;
    padding: 10px 8px;
  }

  .ap-metric:nth-child(odd) {
