.badge.live { background: #e3f2fd; color: #1976d2; }
.badge.demo { background: #f1f3f5; color: #495057; }
.account-id { font-family: monospace; font-weight: 600; }
.metrics { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 12px; }
.metric { display: flex; flex-direction: column; }
.metric span { font-size: 11px; color: #868e96; }
.metric strong { font-size: 14px; color: #212529; }
.footer-row { display: flex; justify-content: space-between; font-size: 11px; color: #495057; border-top: 1px solid #e9ecef; padding-top: 8px; }
.margin-level { font-weight: 600; color: #2f9e44; }
.btn-secondary { background: #1976d2; color: #fff; border: none; padding: 6px 12px; border-radius: 4px; font-size: 12px; cursor: pointer; }
.btn-ghost { background: transparent; color: #1976d2; border: 1px solid #1976d2; padding: 6px 12px; border-radius: 4px; font-size: 12px; cursor: pointer; }

.onboarding-guide-container { display: flex; height: 100%; border: 1px solid #e0e4e8; border-radius: 8px; overflow: hidden; background: #ffffff; }
.progress-sidebar { width: 30%; border-right: 1px solid #e0e4e8; padding: 20px; display: flex; flex-direction: column; justify-content: space-around; background: #f8fafc; }
.step-item { display: flex; align-items: center; gap: 12px; }
.step-icon { width: 24px; height: 24px; border-radius: 50%; background: #cbd5e1; color: white; display: flex; align-items: center; justify-content: center; font-size: 12px; }
.step-item.completed .step-icon { background: #10b981; }
.step-item.active .step-icon { background: #2563eb; }
.step-info label { display: block; font-weight: 600; font-size: 13px; color: #1e293b; }
.step-info span { font-size: 11px; color: #64748b; }
.action-panel { flex: 1; padding: 24px; display: flex; flex-direction: column; justify-content: center; gap: 16px; }
.panel-content h3 { margin: 0 0 8px; font-size: 18px; color: #0f172a; }
.panel-content p { margin: 0; font-size: 13px; color: #475569; line-height: 1.5; }
.button-dock { display: flex; gap: 12px; }
.btn-primary { padding: 8px 20px; border-radius: 4px; border: none; background: #2563eb; color: white; font-weight: 500; cursor: pointer; }
.btn-secondary { padding: 8px 20px; border-radius: 4px; border: 1px solid #cbd5e1; background: white; color: #475569; cursor: pointer; }

.quick-actions-container { padding: 20px; border: 1px solid #e0e4e8; border-radius: 8px; background: #ffffff; height: 100%; display: flex; flex-direction: column; gap: 16px; }
.quick-actions-header .title { font-weight: 600; font-size: 14px; color: #1a1d21; }
.actions-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.action-item { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; padding: 12px 8px; border: 1px solid #f0f2f5; border-radius: 6px; background: #fafbfc; cursor: pointer; transition: all 0.2s; }
.action-item:hover { border-color: #0052cc; background: #f0f7ff; }
.action-item.primary { border-color: #0052cc; background: #eef6ff; }
.action-item.primary .label { color: #0052cc; font-weight: 500; }
.action-item .label { font-size: 12px; color: #4a5568; white-space: nowrap; }
.action-item i { width: 20px; height: 20px; background: currentColor; display: block; -webkit-mask: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/></svg>') no-repeat center; }

.asset-overview-minimal { display: flex; align-items: center; padding: 24px; background: #ffffff; border: 1px solid #eef0f4; border-radius: 8px; gap: 48px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; }
.asset-main { display: flex; flex-direction: column; gap: 4px; min-width: 160px; }
.asset-main .label { font-size: 12px; color: #64748b; }
.asset-main .value { font-size: 20px; font-weight: 600; color: #0f172a; }
.asset-metrics { display: flex; flex: 1; align-items: center; gap: 32px; }
.metric-item { display: flex; flex-direction: column; gap: 4px; }
.metric-item .label { font-size: 12px; color: #64748b; }
.metric-item .value { font-size: 16px; font-weight: 500; color: #1e293b; }
.metric-item .sub { font-size: 11px; color: #94a3b8; }
.divider { width: 1px; height: 32px; background: #e2e8f0; }
@media (max-width: 720px) { .asset-overview-minimal { flex-direction: column; align-items: flex-start; gap: 24px; } .divider { display: none; } }

.faq-section-wrapper { padding: 24px; background: #ffffff; border: 1px solid #eef2f7; border-radius: 8px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; }
.faq-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }
.faq-title { font-size: 16px; font-weight: 600; color: #1a2b3c; margin: 0; }
.faq-view-all { font-size: 13px; color: #0052cc; background: none; border: none; cursor: pointer; font-weight: 500; }
.faq-content { display: flex; flex-direction: column; gap: 12px; }
.faq-item { border-bottom: 1px solid #f4f7fa; padding-bottom: 12px; }
.faq-question { display: flex; justify-content: space-between; font-size: 14px; font-weight: 500; color: #34495e; cursor: pointer; }
.faq-answer { font-size: 13px; color: #7f8c8d; margin-top: 8px; line-height: 1.5; }
.faq-icon { color: #bdc3c7; font-weight: 300; }
@media (max-width: 720px) { .faq-section-wrapper { padding: 16px; } }

.account-performance-3x1 { display: flex; gap: 24px; padding: 20px; background: #fff; border: 1px solid #e5e7eb; border-radius: 8px; height: 100%; box-sizing: border-box; }
.ap-left { flex: 1; display: flex; flex-direction: column; justify-content: space-between; }
.ap-header { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; }
.ap-env { background: #eff6ff; color: #1d4ed8; padding: 2px 8px; border-radius: 4px; font-size: 12px; font-weight: 600; }
.ap-id { color: #6b7280; font-size: 13px; }
.ap-metrics { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.metric-item { display: flex; flex-direction: column; gap: 4px; }
.metric-item .label { color: #6b7280; font-size: 12px; }
.metric-item .value { font-size: 15px; font-weight: 600; color: #111827; }
.ap-actions { display: flex; gap: 8px; margin-top: 16px; }
.btn-primary, .btn-secondary { padding: 6px 16px; border-radius: 4px; font-size: 13px; cursor: pointer; border: 1px solid #e5e7eb; }
.btn-primary { background: #1d4ed8; color: #fff; border: none; }
.btn-secondary { background: #fff; color: #374151; }
.ap-right { flex: 1; display: flex; flex-direction: column; }
.chart-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
.chart-header .title { font-size: 13px; font-weight: 600; }
.tabs button { background: none; border: none; padding: 2px 6px; font-size: 12px; color: #6b7280; cursor: pointer; }
.tabs button.active { color: #1d4ed8; font-weight: 600; }
.chart-container { flex: 1; background: #f9fafb; border-radius: 4px; display: flex; flex-direction: column; padding: 8px; }
.chart-placeholder { flex: 1; border-bottom: 1px dashed #d1d5db; }
.chart-footer { display: flex; gap: 16px; font-size: 12px; color: #6b7280; margin-top: 8px; }
.gain { color: #059669; font-weight: 500; }

.wh-conversion-anchor {
  --wh-bg: #ffffff;
  --wh-border: #e5e7eb;
  --wh-text-primary: #111827;
  --wh-text-secondary: #6b7280;
  --wh-text-tertiary: #9ca3af;
  --wh-blue: #2563eb;
  --wh-blue-hover: #1d4ed8;
  --wh-blue-light: #eff6ff;
  --wh-green: #059669;
  --wh-green-bg: #ecfdf5;
  --wh-radius: 6px;

  background: var(--wh-bg);
  border: 1px solid var(--wh-border);
  border-radius: var(--wh-radius);
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-height: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.wh-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}

.wh-greeting {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  flex: 1;
}

.wh-name-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.wh-client-name {
  font-size: 18px;
  font-weight: 600;
  color: var(--wh-text-primary);
  line-height: 1.3;
  margin: 0;
}

.wh-status-tag {
  font-size: 11px;
  font-weight: 500;
  color: var(--wh-green);
  background: var(--wh-green-bg);
  padding: 3px 10px;
  border-radius: 4px;
  line-height: 1;
  white-space: nowrap;
}

.wh-greeting-text {
  font-size: 13px;
  color: var(--wh-text-secondary);
  margin: 0;
  line-height: 1.5;
}

.wh-metrics {
  display: flex;
  align-items: center;
  gap: 0;
  flex-shrink: 0;
}

.wh-metric {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0 20px;
}

.wh-metric:first-child {
  padding-left: 0;
}

.wh-metric:last-child {
  padding-right: 0;
}

.wh-metric-divider {
  width: 1px;
  height: 32px;
  background: var(--wh-border);
  flex-shrink: 0;
}

.wh-metric-label {
  font-size: 11px;
  color: var(--wh-text-tertiary);
  line-height: 1;
  white-space: nowrap;
}

.wh-metric-value {
  font-size: 18px;
  font-weight: 600;
  color: var(--wh-text-primary);
  line-height: 1.3;
  white-space: nowrap;
}

.wh-actions {
  display: flex;
  gap: 8px;
}

.wh-btn {
  font-size: 13px;
  font-weight: 500;
  padding: 8px 20px;
  border-radius: var(--wh-radius);
  border: none;
  cursor: pointer;
  line-height: 1;
  transition: background-color 0.15s ease;
  white-space: nowrap;
}

.wh-btn-primary {
  background: var(--wh-blue);
  color: #fff;
}

.wh-btn-primary:hover {
  background: var(--wh-blue-hover);
}

.wh-btn-secondary {
  background: #f9fafb;
  color: var(--wh-text-primary);
  border: 1px solid var(--wh-border);
}

.wh-btn-secondary:hover {
  background: #f3f4f6;
}

.wh-btn-ghost {
  background: transparent;
  color: var(--wh-blue);
  padding: 4px 12px;
  font-size: 12px;
  font-weight: 500;
}

.wh-btn-ghost:hover {
  background: var(--wh-blue-light);
}

.wh-status-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--wh-blue-light);
  border-radius: var(--wh-radius);
  border: 1px solid #dbeafe;
}

.wh-status-icon {
  font-size: 13px;
  color: var(--wh-blue);
  font-weight: 500;
  line-height: 1;
  flex-shrink: 0;
}

.wh-status-text {
  font-size: 12px;
  color: var(--wh-text-secondary);
  line-height: 1.5;
  flex: 1;
  min-width: 0;
}

@media (max-width: 720px) {
  .wh-conversion-anchor {
    padding: 16px;
    gap: 14px;
  }

  .wh-top {
    flex-direction: column;
    gap: 16px;
  }

  .wh-metrics {
    width: 100%;
    justify-content: flex-start;
  }

  .wh-metric {
    flex: 1;
    padding: 0 16px;
  }

  .wh-metric:first-child {
    padding-left: 0;
  }

  .wh-metric:last-child {
    padding-right: 0;
  }

  .wh-actions {
    width: 100%;
  }

  .wh-btn {
    flex: 1;
    text-align: center;
    padding: 10px 16px;
  }

  .wh-status-bar {
    flex-wrap: wrap;
    gap: 8px;
  }

  .wh-status-text {
    width: 100%;
    order: 2;
  }

  .wh-btn-ghost {
    order: 3;
    margin-left: auto;
  }
}

@media (max-width: 480px) {
  .wh-metrics {
    flex-direction: column;
    gap: 12px;
  }

  .wh-metric {
    padding: 0;
    width: 100%;
    flex-direction: row;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
  }

  .wh-metric-divider {
    display: none;
  }

  .wh-metric-label {
    white-space: normal;
  }
}

.pb-deposit-ladder {
  display: flex;
  width: 100%;
  min-height: 180px;
  background: #f6f7f9;
  border-radius: 6px;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.pb-dl-main {
  flex: 1;
  padding: 24px 28px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.pb-dl-status {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.pb-dl-badge {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 8px;
  background: #10b981;
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  border-radius: 4px;
  letter-spacing: 0.02em;
}

.pb-dl-period {
  font-size: 12px;
  color: #6b7280;
  font-weight: 400;
}

.pb-dl-title {
  font-size: 18px;
  font-weight: 700;
  color: #111827;
  margin: 0 0 6px 0;
  line-height: 1.3;
}

.pb-dl-desc {
  font-size: 13px;
  color: #6b7280;
  margin: 0 0 16px 0;
  line-height: 1.5;
  max-width: 480px;
}

.pb-dl-tiers {
  display: flex;
  gap: 8px;
  margin-bottom: 12px;
}

.pb-dl-tier {
  flex: 1;
  position: relative;
  background: #e5e7eb;
  border-radius: 4px;
  overflow: hidden;
  height: 48px;
}

.pb-dl-tier--active {
  background: #dbeafe;
}

.pb-dl-tier--current {
  background: #e5e7eb;
}

.pb-dl-tier-bar {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  background: #3b82f6;
  border-radius: 4px;
  transition: width 0.3s ease;
}

.pb-dl-tier--active .pb-dl-tier-bar {
  background: #10b981;
}

.pb-dl-tier-inner {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  gap: 2px;
}

.pb-dl-tier-amount {
  font-size: 12px;
  font-weight: 600;
  color: #374151;
}

.pb-dl-tier-reward {
  font-size: 11px;
  font-weight: 700;
  color: #059669;
}

.pb-dl-tier--current .pb-dl-tier-reward {
  color: #2563eb;
}

.pb-dl-progress {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #6b7280;
  margin-bottom: 8px;
}

.pb-dl-progress strong {
  color: #111827;
  font-weight: 700;
}

.pb-dl-unlocked {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #059669;
  font-weight: 500;
}

.pb-dl-unlocked-dot {
  width: 6px;
  height: 6px;
  background: #10b981;
  border-radius: 50%;
}

.pb-dl-side {
  width: 220px;
  padding: 24px 28px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-left: 1px solid #e5e7eb;
  background: #fff;
}

.pb-dl-dock {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 14px;
}

.pb-dl-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 36px;
  padding: 0 16px;
  border-radius: 4px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: background 0.15s ease;
}

.pb-dl-btn--primary {
  background: #2563eb;
  color: #fff;
}

.pb-dl-btn--primary:hover {
  background: #1d4ed8;
}

.pb-dl-btn--secondary {
  background: transparent;
  color: #374151;
  border: 1px solid #d1d5db;
}

.pb-dl-btn--secondary:hover {
  background: #f9fafb;
}

.pb-dl-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 8px;
  font-size: 11px;
  color: #9ca3af;
  line-height: 1.4;
}

@media (max-width: 768px) {
  .pb-deposit-ladder {
    flex-direction: column;
  }

  .pb-dl-side {
    width: 100%;
    border-left: none;
    border-top: 1px solid #e5e7eb;
    padding: 20px 24px;
  }

  .pb-dl-main {
    padding: 20px 24px;
  }

  .pb-dl-tiers {
    gap: 6px;
  }

  .pb-dl-tier {
    height: 44px;
  }

  .pb-dl-dock {
    flex-direction: row;
  }

  .pb-dl-btn {
    flex: 1;
  }
}

.ao-ticker-strip {
  --ao-bg: #ffffff;
  --ao-surface: #f8fafc;
  --ao-border: #e2e8f0;
  --ao-text-primary: #0f172a;
  --ao-text-secondary: #64748b;
  --ao-text-tertiary: #94a3b8;
  --ao-accent: #2563eb;
  --ao-accent-light: #dbeafe;
  --ao-pulse: #22c55e;
  --ao-success: #16a34a;
  --ao-radius: 6px;

  width: 100%;
  background: var(--ao-bg);
  border: 1px solid var(--ao-border);
  border-radius: var(--ao-radius);
  padding: 20px 24px;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.ao-ticker-strip__header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.ao-ticker-strip__pulse {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ao-pulse);
  position: relative;
  flex-shrink: 0;
}

.ao-ticker-strip__pulse::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: var(--ao-pulse);
  opacity: 0.3;
  animation: ao-pulse-ring 2s ease-out infinite;
}

@keyframes ao-pulse-ring {
  0% { transform: scale(1); opacity: 0.3; }
  100% { transform: scale(2.5); opacity: 0; }
}

.ao-ticker-strip__currency {
  font-size: 11px;
  font-weight: 600;
  color: var(--ao-accent);
  background: var(--ao-accent-light);
  padding: 2px 8px;
  border-radius: 4px;
  letter-spacing: 0.02em;
  flex-shrink: 0;
}

.ao-ticker-strip__label {
  font-size: 13px;
  color: var(--ao-text-secondary);
  font-weight: 400;
}

.ao-ticker-strip__total {
  font-size: 22px;
  font-weight: 700;
  color: var(--ao-text-primary);
  letter-spacing: -0.02em;
  margin-left: auto;
}

.ao-ticker-strip__divider {
  height: 1px;
  background: var(--ao-border);
  margin-bottom: 14px;
}

.ao-ticker-strip__metrics {
  display: flex;
  align-items: stretch;
  gap: 0;
}

.ao-ticker-strip__metric {
  flex: 1;
  padding: 0 16px;
  min-width: 0;
}

.ao-ticker-strip__metric:first-child {
  padding-left: 0;
}

.ao-ticker-strip__metric:last-child {
  padding-right: 0;
}

.ao-ticker-strip__metric-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}

.ao-ticker-strip__metric-label {
  font-size: 12px;
  color: var(--ao-text-secondary);
  font-weight: 400;
  white-space: nowrap;
}

.ao-ticker-strip__metric-value {
  font-size: 15px;
  font-weight: 600;
  color: var(--ao-text-primary);
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.ao-ticker-strip__metric-detail {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.ao-ticker-strip__currency-tag,
  .ao-ticker-strip__account-type,
  .ao-ticker-strip__avail-tag {
  font-size: 11px;
  color: var(--ao-text-tertiary);
  font-weight: 400;
}

.ao-ticker-strip__count {
  font-size: 11px;
  color: var(--ao-text-secondary);
  font-weight: 500;
  margin-left: auto;
}

.ao-ticker-strip__account-sep,
  .ao-ticker-strip__avail-sep {
  font-size: 11px;
  color: var(--ao-text-tertiary);
}

.ao-ticker-strip__metric-divider {
  width: 1px;
  background: var(--ao-border);
  flex-shrink: 0;
}

.ao-ticker-strip__footer-line {
  height: 1px;
  background: var(--ao-border);
  margin-top: 14px;
  margin-bottom: 8px;
}

.ao-ticker-strip__footer-hint {
  text-align: center;
}

.ao-ticker-strip__footer-hint span {
  font-size: 11px;
  color: var(--ao-text-tertiary);
