.rlc-card {
  --rlc-bg: #ffffff;
  --rlc-border: #e8ecf1;
  --rlc-text: #1a1d2b;
  --rlc-text-secondary: #6b7280;
  --rlc-text-tertiary: #9ca3af;
  --rlc-blue: #2563eb;
  --rlc-blue-light: #eff6ff;
  --rlc-blue-hover: #1d4ed8;
  --rlc-green: #059669;
  --rlc-green-bg: #ecfdf5;
  --rlc-radius: 6px;
  --rlc-gap: 16px;
  --rlc-pad: 20px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--rlc-bg);
  border: 1px solid var(--rlc-border);
  border-radius: var(--rlc-radius);
  padding: var(--rlc-pad);
  display: flex;
  flex-direction: column;
  gap: var(--rlc-gap);
  min-height: 0;
  height: 100%;
  box-sizing: border-box;
}

.rlc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}

.rlc-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--rlc-text);
  margin: 0;
  line-height: 1.3;
}

.rlc-status {
  font-size: 11px;
  font-weight: 500;
  color: var(--rlc-green);
  background: var(--rlc-green-bg);
  padding: 2px 8px;
  border-radius: 4px;
  line-height: 1.5;
}

.rlc-body {
  display: flex;
  gap: 20px;
  flex: 1;
  min-height: 0;
  align-items: stretch;
}

.rlc-left {
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
  min-width: 0;
  justify-content: center;
}

.rlc-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.rlc-label {
  font-size: 11px;
  font-weight: 500;
  color: var(--rlc-text-tertiary);
  text-transform: none;
  letter-spacing: 0;
  line-height: 1.4;
}

.rlc-value-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.rlc-code {
  font-size: 18px;
  font-weight: 700;
  color: var(--rlc-text);
  letter-spacing: 0.5px;
  line-height: 1.2;
}

.rlc-link {
  font-size: 12px;
  color: var(--rlc-text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  min-width: 0;
  line-height: 1.4;
}

.rlc-btn-ghost {
  font-size: 11px;
  font-weight: 500;
  color: var(--rlc-blue);
  background: transparent;
  border: none;
  padding: 2px 6px;
  cursor: pointer;
  flex-shrink: 0;
  line-height: 1.4;
  transition: color 0.15s ease;
}

.rlc-btn-ghost:hover {
  color: var(--rlc-blue-hover);
}

.rlc-right {
  display: flex;
  gap: 0;
  flex-shrink: 0;
  align-items: center;
}

.rlc-metric {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 0 14px;
  position: relative;
}

.rlc-metric:not(:last-child)::after {
  content: "";
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1px;
  height: 28px;
  background: var(--rlc-border);
}

.rlc-metric-val {
  font-size: 17px;
  font-weight: 700;
  color: var(--rlc-text);
  line-height: 1.2;
}

.rlc-metric-label {
  font-size: 11px;
  color: var(--rlc-text-tertiary);
  line-height: 1.3;
}

.rlc-metric-rate {
  font-size: 10px;
  font-weight: 500;
  color: var(--rlc-green);
  line-height: 1.3;
}

.rlc-footer {
  display: flex;
  gap: 10px;
  flex-shrink: 0;
  padding-top: 4px;
}

.rlc-btn-primary,
.rlc-btn-secondary {
  font-size: 12px;
  font-weight: 500;
  padding: 7px 14px;
  border-radius: var(--rlc-radius);
  cursor: pointer;
  line-height: 1.4;
  transition: all 0.15s ease;
  flex: 1;
  text-align: center;
}

.rlc-btn-primary {
  color: #ffffff;
  background: var(--rlc-blue);
  border: 1px solid var(--rlc-blue);
}

.rlc-btn-primary:hover {
  background: var(--rlc-blue-hover);
  border-color: var(--rlc-blue-hover);
}

.rlc-btn-secondary {
  color: var(--rlc-text-secondary);
  background: #f8fafc;
  border: 1px solid var(--rlc-border);
}

.rlc-btn-secondary:hover {
  background: #f1f5f9;
  border-color: #d1d5db;
}

@media (max-width: 720px) {
  .rlc-card {
    --rlc-pad: 16px;
    --rlc-gap: 14px;
  }

  .rlc-body {
    flex-direction: column;
    gap: 14px;
  }

  .rlc-right {
    justify-content: space-between;
    padding: 12px 0;
    border-top: 1px solid var(--rlc-border);
    border-bottom: 1px solid var(--rlc-border);
  }

  .rlc-metric {
    flex: 1;
    padding: 0;
    align-items: flex-start;
    flex-direction: row;
    gap: 6px;
    flex-wrap: wrap;
  }

  .rlc-metric:not(:last-child)::after {
    display: none;
  }

  .rlc-metric-val {
    font-size: 15px;
  }

  .rlc-footer {
    padding-top: 2px;
  }

  .rlc-btn-primary,
  .rlc-btn-secondary {
    padding: 8px 12px;
  }
}

