.ao-ticker-strip {
  --ao-text-primary: #1a1a2e;
  --ao-text-secondary: #5a6a7a;
  --ao-text-tertiary: #8a94a0;
  --ao-border: #e8ecf1;
  --ao-surface: #f7f9fb;
  --ao-accent: #2563eb;
  --ao-accent-light: #dbeafe;
  --ao-credit: #7c3aed;
  --ao-credit-light: #ede9fe;
  --ao-success: #059669;
  --ao-radius: 6px;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'PingFang SC', 'Hiragino Sans GB', sans-serif;
  background: #fff;
  border: 1px solid var(--ao-border);
  border-radius: var(--ao-radius);
  padding: 20px 24px;
  width: 100%;
  box-sizing: border-box;
}

.ao-header {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.ao-pulse-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.ao-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ao-success);
  position: relative;
  flex-shrink: 0;
}

.ao-pulse::after {
  content: '';
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: var(--ao-success);
  opacity: 0.25;
  animation: ao-pulse-ring 2s ease-out infinite;
}

@keyframes ao-pulse-ring {
  0% { transform: scale(1); opacity: 0.25; }
  100% { transform: scale(2.2); opacity: 0; }
}

.ao-currency {
  font-size: 11px;
  font-weight: 600;
  color: var(--ao-text-tertiary);
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.ao-total-group {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.ao-total-label {
  font-size: 13px;
  color: var(--ao-text-secondary);
  font-weight: 500;
}

.ao-total-value {
  font-size: 22px;
  font-weight: 700;
  color: var(--ao-text-primary);
  letter-spacing: -0.3px;
}

.ao-account-badge {
  margin-left: auto;
  font-size: 11px;
  color: var(--ao-text-tertiary);
  background: var(--ao-surface);
  padding: 3px 10px;
  border-radius: 4px;
  font-weight: 500;
}

.ao-divider {
  height: 1px;
  background: var(--ao-border);
  margin: 14px 0;
}

