.ct-signals-v3 {
  --ct-primary: #2563eb;
  --ct-primary-hover: #1d4ed8;
  --ct-success: #059669;
  --ct-bg: #ffffff;
  --ct-surface: #f8fafc;
  --ct-border: #e2e8f0;
  --ct-text: #0f172a;
  --ct-text-secondary: #64748b;
  --ct-text-tertiary: #94a3b8;
  --ct-risk-low: #059669;
  --ct-risk-low-bg: #ecfdf5;
  --ct-risk-mid: #d97706;
  --ct-risk-mid-bg: #fffbeb;
  --ct-risk-high: #dc2626;
  --ct-risk-high-bg: #fef2f2;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--ct-bg);
  border: 1px solid var(--ct-border);
  border-radius: 6px;
  padding: 20px 24px 24px;
  width: 100%;
  box-sizing: border-box;
}
.ct-signals-v3 * { box-sizing: border-box; margin: 0; padding: 0; }

.ct-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 14px;
}
.ct-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--ct-text);
  line-height: 1.4;
  letter-spacing: -0.01em;
}
.ct-more {
  font-size: 13px;
  color: var(--ct-primary);
  text-decoration: none;
  font-weight: 500;
  transition: color 0.15s;
}
.ct-more:hover { color: var(--ct-primary-hover); }

.ct-band {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  background: var(--ct-surface);
  border-radius: 6px;
  margin-bottom: 16px;
}
.ct-band-item {
  display: flex;
  align-items: baseline;
  gap: 6px;
}
.ct-band-num {
  font-size: 15px;
  font-weight: 600;
  color: var(--ct-text);
}
.ct-band-label {
  font-size: 12px;
  color: var(--ct-text-secondary);
}
.ct-band-dot {
  color: var(--ct-text-tertiary);
  font-size: 12px;
}

.ct-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.ct-card {
  border: 1px solid var(--ct-border);
  border-radius: 6px;
  padding: 16px;
  background: var(--ct-bg);
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.ct-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}
.ct-signal-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--ct-text);
}
.ct-risk {
  font-size: 11px;
  font-weight: 500;
  padding: 3px 8px;
  border-radius: 4px;
  line-height: 1;
}
.ct-risk--low { color: var(--ct-risk-low); background: var(--ct-risk-low-bg); }
.ct-risk--mid { color: var(--ct-risk-mid); background: var(--ct-risk-mid-bg); }
.ct-risk--high { color: var(--ct-risk-high); background: var(--ct-risk-high-bg); }

.ct-metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-bottom: 10px;
}
.ct-metric {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.ct-metric--primary .ct-metric-value {
  font-size: 18px;
  font-weight: 700;
}
.ct-metric-label {
  font-size: 11px;
  color: var(--ct-text-tertiary);
  line-height: 1.3;
}
.ct-metric-value {
  font-size: 14px;
  font-weight: 600;
  color: var(--ct-text);
  line-height: 1.3;
}
.ct-metric-value--up { color: var(--ct-success); }

.ct-drawdown {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--ct-border);
}
.ct-drawdown-label {
  font-size: 11px;
  color: var(--ct-text-tertiary);
}
.ct-drawdown-value {
  font-size: 12px;
  font-weight: 500;
  color: var(--ct-text-secondary);
}

.ct-chart-wrap {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  margin-bottom: 12px;
}
.ct-chart-tabs {
  display: flex;
  gap: 2px;
  margin-bottom: 8px;
}
.ct-chart-tab {
  font-size: 11px;
  font-weight: 500;
  color: var(--ct-text-tertiary);
  background: none;
  border: none;
  padding: 3px 8px;
  border-radius: 4px;
  cursor: pointer;
  line-height: 1;
}
.ct-chart-tab--active {
  color: var(--ct-primary);
  background: #eff6ff;
}
.ct-chart-area {
  flex: 1;
  min-height: 48px;
  position: relative;
}
.ct-chart-area svg {
  width: 100%;
  height: 100%;
  display: block;
}

.ct-dock {
  margin-top: auto;
  padding-top: 4px;
}
.ct-btn {
  width: 100%;
  padding: 8px 0;
  font-size: 13px;
  font-weight: 500;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.15s;
  line-height: 1;
  border: none;
}
.ct-btn--primary {
  background: var(--ct-primary);
  color: #fff;
}
.ct-btn--primary:hover { background: var(--ct-primary-hover); }
.ct-btn--ghost {
  background: transparent;
  color: var(--ct-text-secondary);
  border: 1px solid var(--ct-border);
}
.ct-btn--ghost:hover {
  background: var(--ct-surface);
  color: var(--ct-text);
}

@media (max-width: 768px) {
  .ct-grid { grid-template-columns: 1fr; }
  .ct-signals-v3 { padding: 16px; }
  .ct-metrics { grid-template-columns: 1fr 1fr; }
}

@media (min-width: 769px) and (max-width: 1024px) {
  .ct-grid { grid-template-columns: repeat(2, 1fr); }
  .ct-card:last-child { display: none; }
}

