  background: #e8ffea;
  color: #00b42a;
}

.is-completed .step-status {
  color: #00b42a;
  font-weight: 500;
}

/* Active State */
.is-active .step-icon {
  background: #0052ff;
  color: #ffffff;
  box-shadow: 0 4px 10px rgba(0, 82, 255, 0.2);
}

.is-active .step-desc {
  font-size: 12px;
  color: #4e5969;
  margin-bottom: 12px;
}

.step-action-dock {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: flex-start;
}

.btn-primary {
  background: #0052ff;
  color: #ffffff;
  border: none;
  padding: 8px 16px;
  border-radius: 4px;
  font-size: 13px;
  font-weight: 500;
