  }
  .wh-action-dock {
    width: 100%;
  }
  .wh-btn {
    flex: 1;
  }
  .wh-notice span {
    white-space: normal;
  }
}

.fx-ao-lightbar {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 24px;
  box-sizing: border-box;
  width: 100%;
}

.fx-ao-primary {
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  margin-right: 32px;
}

.fx-ao-label {
  display: flex;
  align-items: center;
  color: #64748b;
  font-size: 13px;
  font-weight: 500;
  margin-bottom: 6px;
}

.fx-ao-pulse {
  width: 6px;
  height: 6px;
  background-color: #10b981;
  border-radius: 50%;
  margin-right: 8px;
  box-shadow: 0 0 0 rgba(16, 185, 129, 0.4);
  animation: fx-ao-pulse-anim 2s infinite;
}

@keyframes fx-ao-pulse-anim {
  0% {
    box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.4);
  }
  70% {
    box-shadow: 0 0 0 6px rgba(16, 185, 129, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(16, 185, 129, 0);
  }
}

.fx-ao-total {
  color: #0f172a;
  font-size: 28px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.5px;
}

.fx-ao-actions {
  display: flex;
  align-items: center;
  margin-top: 10px;
  gap: 8px;
}

.fx-ao-link {
  color: #2563eb;
  font-size: 13px;
  font-weight: 500;
  text-decoration: none;
  transition: color 0.2s ease;
}

.fx-ao-link:hover {
  color: #1d4ed8;
}

.fx-ao-dot {
  color: #cbd5e1;
  font-size: 12px;
}

.fx-ao-secondary {
  display: flex;
  align-items: center;
  background: #f8fafc;
  border-radius: 6px;
  padding: 16px 24px;
  flex-grow: 1;
  max-width: 600px;
}

.fx-ao-metric {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.fx-ao-metric-head {
  display: flex;
  align-items: center;
  color: #64748b;
  font-size: 13px;
  margin-bottom: 6px;
}

.fx-ao-icon {
  width: 14px;
  height: 14px;
  margin-right: 6px;
  opacity: 0.7;
}

.fx-ao-val {
  color: #0f172a;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.4;
}

.fx-ao-desc {
  color: #94a3b8;
  font-size: 12px;
  margin-top: 2px;
}

.fx-ao-divider {
  width: 1px;
  height: 48px;
  background-color: #e2e8f0;
  margin: 0 24px;
}

@media (max-width: 860px) {
  .fx-ao-lightbar {
    flex-direction: column;
    align-items: flex-start;
    padding: 20px;
  }

  .fx-ao-primary {
    margin-right: 0;
    margin-bottom: 20px;
  }

  .fx-ao-secondary {
    width: 100%;
    max-width: 100%;
    box-sizing: border-box;
  }
}

@media (max-width: 480px) {
  .fx-ao-secondary {
    flex-direction: column;
    align-items: flex-start;
    padding: 16px;
  }

  .fx-ao-metric {
    width: 100%;
  }

  .fx-ao-divider {
    width: 100%;
    height: 1px;
    margin: 16px 0;
  }
}

.fx-faq-3x1-compact {
  display: flex;
  flex-direction: row;
  gap: 24px;
  background-color: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 24px;
  box-sizing: border-box;
  width: 100%;
}

.fx-faq-3x1-compact .faq-sidebar {
  flex: 0 0 220px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding-right: 24px;
  border-right: 1px solid #f1f5f9;
}

.fx-faq-3x1-compact .faq-header {
  margin-bottom: 16px;
}

.fx-faq-3x1-compact .faq-title {
  font-size: 16px;
  font-weight: 600;
  color: #0f172a;
  margin: 0 0 8px 0;
}

.fx-faq-3x1-compact .faq-desc {
  font-size: 13px;
  color: #64748b;
  margin: 0;
  line-height: 1.5;
}

.fx-faq-3x1-compact .faq-btn {
  align-self: flex-start;
  padding: 6px 16px;
  font-size: 13px;
  font-weight: 500;
  color: #0284c7;
  background-color: #f0f9ff;
  border: 1px solid #bae6fd;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
}

.fx-faq-3x1-compact .faq-btn:hover {
  background-color: #e0f2fe;
}

.fx-faq-3x1-compact .faq-content {
  flex: 1;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px 32px;
}

.fx-faq-3x1-compact .faq-item {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.fx-faq-3x1-compact .faq-q {
  font-size: 14px;
  font-weight: 500;
  color: #1e293b;
  display: flex;
  align-items: flex-start;
  gap: 6px;
  line-height: 1.4;
}

.fx-faq-3x1-compact .faq-icon {
  color: #0284c7;
  font-weight: 600;
  font-size: 14px;
}

.fx-faq-3x1-compact .faq-a {
  font-size: 13px;
  color: #475569;
  line-height: 1.5;
  padding-left: 21px;
}

@media (max-width: 992px) {
  .fx-faq-3x1-compact {
    flex-direction: column;
    gap: 20px;
  }
  .fx-faq-3x1-compact .faq-sidebar {
    flex: auto;
    border-right: none;
    border-bottom: 1px solid #f1f5f9;
    padding-right: 0;
    padding-bottom: 20px;
    flex-direction: row;
    align-items: center;
  }
  .fx-faq-3x1-compact .faq-header {
    margin-bottom: 0;
  }
}

@media (max-width: 640px) {
  .fx-faq-3x1-compact .faq-sidebar {
    flex-direction: column;
    align-items: flex-start;
    gap: 16px;
  }
  .fx-faq-3x1-compact .faq-content {
    grid-template-columns: 1fr;
    gap: 24px;
  }
}

.fx-risk-strip {
    display: flex;
    gap: 24px;
    padding: 20px 24px;
    background-color: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    color: #475569;
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    line-height: 1.6;
    box-sizing: border-box;
    width: 100%;
}

.fx-risk-header {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    flex-shrink: 0;
    width: 100px;
    color: #64748b;
    padding-top: 2px;
}

.fx-risk-header svg {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    margin-top: 3px;
}

.fx-risk-header strong {
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.5px;
}

.fx-risk-content {
    display: flex;
    flex-direction: column;
    gap: 8px;
    font-size: 12px;
    flex-grow: 1;
}

.fx-risk-content p {
    margin: 0;
}

.fx-risk-footer {
    color: #94a3b8;
    margin-top: 4px;
}

.fx-risk-footer a {
    color: #64748b;
    text-decoration: none;
    margin-left: 8px;
    transition: color 0.2s ease;
}

.fx-risk-footer a:hover {
    color: #0f172a;
}

@media (max-width: 768px) {
    .fx-risk-strip {
        flex-direction: column;
        gap: 12px;
        padding: 16px;
    }
    .fx-risk-header {
        width: auto;
        align-items: center;
        padding-top: 0;
    }
    .fx-risk-header svg {
        margin-top: 0;
    }
}
